begin;
create function pg_temp.qsr_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'QSHE scope: %',label;end if;end $$;
insert into public.branches(code,name) values('QSRD','[UJI] QSHE scope'),('QSOT','[UJI] Other branch');
insert into auth.users(id) values('dc110000-0000-4000-8000-000000000001'),('dc110000-0000-4000-8000-000000000002');
insert into public.profiles(id,branch_code,full_name,is_active) values('dc110000-0000-4000-8000-000000000001','QSRD','[UJI] QSHE without portfolio',true),('dc110000-0000-4000-8000-000000000002','QSOT','[UJI] Other QSHE',true);
insert into public.user_role_assignments(profile_id,branch_code,role_code,grant_reason) values('dc110000-0000-4000-8000-000000000001','QSRD','qshe','[UJI] Read scope'),('dc110000-0000-4000-8000-000000000002','QSOT','qshe','[UJI] Read scope');
insert into public.equipment(id,branch_code,name,ownership) values('dc120000-0000-4000-8000-000000000001','QSRD','[UJI] Visible tool','internal'),('dc120000-0000-4000-8000-000000000002','QSOT','[UJI] Outside tool','internal');
insert into public.calibrations(id,branch_code,equipment_id,certificate_number,issue_date,due_date) values('dc130000-0000-4000-8000-000000000001','QSRD','dc120000-0000-4000-8000-000000000001','[UJI] CAL','2026-01-01','2027-01-01');
select set_config('request.jwt.claim.sub','dc110000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"aal":"aal1"}',true);
set local role authenticated;
select pg_temp.qsr_assert((select count(*)=1 from public.equipment),'QSHE sees only own branch without portfolio assignment');
select pg_temp.qsr_assert((select count(*)=1 from public.equipment_monitoring_records),'monitoring view includes own branch equipment');
select pg_temp.qsr_assert((select count(*)=1 from public.calibrations),'calibration history visible');
select pg_temp.qsr_assert(private.document_scope('QSRD','calibration','dc130000-0000-4000-8000-000000000001',false),'certificate scope available for QC');
select pg_temp.qsr_assert(not private.equipment_scope('QSRD','dc120000-0000-4000-8000-000000000001',true),'QSHE does not gain editing rights');
do $$ declare changed integer;begin
 update public.equipment set name='Forbidden' where id='dc120000-0000-4000-8000-000000000001';get diagnostics changed=row_count;
 perform pg_temp.qsr_assert(changed=0,'equipment update remains blocked');
 update public.calibrations set certificate_number='Forbidden' where id='dc130000-0000-4000-8000-000000000001';get diagnostics changed=row_count;
 perform pg_temp.qsr_assert(changed=0,'calibration update remains blocked');
end $$;
select pg_temp.qsr_assert(not private.equipment_scope('QSOT','dc120000-0000-4000-8000-000000000002',false),'cannot cross branches');
reset role;
select set_config('request.jwt.claim.sub','',true);
update public.user_role_assignments set is_active=false where profile_id='dc110000-0000-4000-8000-000000000001';
select set_config('request.jwt.claim.sub','dc110000-0000-4000-8000-000000000001',true);
set local role authenticated;
select pg_temp.qsr_assert((select count(*)=0 from public.equipment),'revoked role loses read access');
reset role;
select 'PASS: QSHE branch read without portfolio, monitoring and certificate scope, no write or cross-branch access, revoked grant blocked' as result;
rollback;
